draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

var padL = 44, padB = 34, padT = 16, padR = 16;
var cols = 9, rows = 7;
var cw = (W - padL - padR) / cols;
var ch = (H - padT - padB) / rows;
var X = function (c) { return padL + cw * (c + 0.5); };
var Y = function (r) { return H - padB - ch * (r + 0.5); };

// grid
ctx.strokeStyle = C.faint;
var i;
for (i = 0; i <= cols; i++) {
  ctx.beginPath(); ctx.moveTo(padL + cw * i, padT); ctx.lineTo(padL + cw * i, H - padB); ctx.stroke();
}
for (i = 0; i <= rows; i++) {
  ctx.beginPath(); ctx.moveTo(padL, H - padB - ch * i); ctx.lineTo(W - padR, H - padB - ch * i); ctx.stroke();
}

ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(padL, padT); ctx.lineTo(padL, H - padB); ctx.lineTo(W - padR, H - padB);
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("neutron number N", (padL + W - padR) / 2, H - 6);
ctx.save();
ctx.translate(12, (padT + H - padB) / 2);
ctx.rotate(-Math.PI / 2);
ctx.fillText("proton number Z", 0, 0);
ctx.restore();

var arrow = function (c0, r0, c1, r1, label, lx, ly) {
  var x0 = X(c0), y0 = Y(r0), x1 = X(c1), y1 = Y(r1);
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var a = Math.atan2(y1 - y0, x1 - x0);
  ctx.fillStyle = C.accent;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 8 * Math.cos(a - 0.4), y1 - 8 * Math.sin(a - 0.4));
  ctx.lineTo(x1 - 8 * Math.cos(a + 0.4), y1 - 8 * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
  ctx.fillStyle = C.ink;
  ctx.textAlign = "left";
  ctx.fillText(label, x1 + lx, y1 + ly);
};

// the parent nucleus, centre
var pc = 4, pr = 3;
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(X(pc), Y(pr), 6, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("parent", X(pc), Y(pr) - 12);

arrow(pc, pr, pc - 2, pr - 2, "alpha: A-4, Z-2", 6, 4);
arrow(pc, pr, pc - 1, pr + 1, "beta minus: Z+1", 6, -4);
arrow(pc, pr, pc + 1, pr - 1, "beta plus / EC: Z-1", -110, 16);

// gamma: same square, small loop
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.arc(X(pc) + 14, Y(pr) + 14, 10, Math.PI * 0.9, Math.PI * 2.6);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("gamma: A, Z unchanged", X(pc) + 26, Y(pr) + 22);

ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("each square is one nuclide; one step right adds a neutron", padL + 4, padT + 12);

out.note = "alpha moves two squares down-left; beta-minus trades a neutron for a proton";
